# [HELPER] model_client.py\nimport os\nfrom typing import Any, Dict\n\n# Detect provider from environment variables\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\").lower()\n\n# Provider-specific imports – fallback to a no‑op stub if not available\ntry:\n    if PROVIDER == \"openai\":\n        import openai\n        openai.api_key = os.getenv(\"OPENAI_API_KEY\")\n    elif PROVIDER == \"anthropic\":\n        import anthropic\n        anthropic.api_key = os.getenv(\"ANTHROPIC_API_KEY\")\n    elif PROVIDER == \"google-genai\":\n        import google.generativeai as genai\n        genai.configure(api_key=os.getenv(\"GOOGLE_API_KEY\"))\n    elif PROVIDER == \"mistral\":\n        from mistralai.services.chat_client import ChatClient\n        from mistralai.utils.auth import BearerAuth\n        MISTRAL_API_KEY = os.getenv(\"MISTRAL_API_KEY\")\n        client = ChatClient(auth=BearerAuth(MISTRAL_API_KEY))\n    elif PROVIDER == \"dashscope\":\n        import dashscope\n        dashscope.api_key = os.getenv(\"DASHSCOPE_API_KEY\")\n    else:\n        # Default to OpenAI stub\n        import openai\n        openai.api_key = \"dummy\"\nexcept ImportError:\n    # Simple stub when the SDK is not installed\n    class Stub:\n        def chat_completions(self, request):\n            return {\"choices\": [{\"message\": {\"content\": \"stub response\"}}]}\n        def chat_completions_stream(self, request):\n            yield {\"content\": \"stub streamed\"}\n    openai = Stub()\n    anthropic = Stub()\n    genai = Stub()\n    dashscope = Stub()\n    ChatClient = lambda **kw: Stub()\n\ndef get_llm_client() -> Any:\n    \"\"\"Return a provider‑specific client object with compatible chat_completions methods.\"\"\"\n    if PROVIDER == \"openai\":\n        return openai\n    elif PROVIDER == \"anthropic\":\n        return anthropic\n    elif PROVIDER == \"google-genai\":\n        return genai\n    elif PROVIDER == \"mistral\":\n        return ChatClient()\n    elif PROVIDER == \"dashscope\":\n        return dashscope\n    else:\n        return openai  # fallback\n